// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * The first failed check. `badge_failure_code` gives the code of the spec and the vectors.
 */

public enum BadgeFailure: Equatable, Hashable {
    
    case unsupportedVersion
    case unknownKid
    case invalidSignature
    case malformed
    case expired
    case notYetValid
    case subjectMismatch
    case masterKeyMismatch
    /**
     * Steps 2, 6 to 9 and 12 of "Verification order": only `verify_issued_badge` gives these.
     */
    case unknownIssuer
    case issuerMismatch
    case levelNotAllowed
    case unknownScheme
    case schemeNotAllowed
    case schemeMismatch
    case lifeTooLong
    case regionMismatch





}

#if compiler(>=6)
extension BadgeFailure: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBadgeFailure: FfiConverterRustBuffer {
    typealias SwiftType = BadgeFailure

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BadgeFailure {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .unsupportedVersion
        
        case 2: return .unknownKid
        
        case 3: return .invalidSignature
        
        case 4: return .malformed
        
        case 5: return .expired
        
        case 6: return .notYetValid
        
        case 7: return .subjectMismatch
        
        case 8: return .masterKeyMismatch
        
        case 9: return .unknownIssuer
        
        case 10: return .issuerMismatch
        
        case 11: return .levelNotAllowed
        
        case 12: return .unknownScheme
        
        case 13: return .schemeNotAllowed
        
        case 14: return .schemeMismatch
        
        case 15: return .lifeTooLong
        
        case 16: return .regionMismatch
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BadgeFailure, into buf: inout [UInt8]) {
        switch value {
        
        
        case .unsupportedVersion:
            writeInt(&buf, Int32(1))
        
        
        case .unknownKid:
            writeInt(&buf, Int32(2))
        
        
        case .invalidSignature:
            writeInt(&buf, Int32(3))
        
        
        case .malformed:
            writeInt(&buf, Int32(4))
        
        
        case .expired:
            writeInt(&buf, Int32(5))
        
        
        case .notYetValid:
            writeInt(&buf, Int32(6))
        
        
        case .subjectMismatch:
            writeInt(&buf, Int32(7))
        
        
        case .masterKeyMismatch:
            writeInt(&buf, Int32(8))
        
        
        case .unknownIssuer:
            writeInt(&buf, Int32(9))
        
        
        case .issuerMismatch:
