fileprivate struct FfiConverterSequenceTypeTrustedKey: FfiConverterRustBuffer {
    typealias SwiftType = [TrustedKey]

    public static func write(_ value: [TrustedKey], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeTrustedKey.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [TrustedKey] {
        let len: Int32 = try readInt(&buf)
        var seq = [TrustedKey]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeTrustedKey.read(from: &buf))
        }
        return seq
    }
}

